begin;
select no_plan();
insert into auth.users(id,email) values ('11111111-1111-4111-8111-111111111711','evidence-v2@example.invalid');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111711',true);
select is(jsonb_object_length,30,'canonical basis contract has 30 codes') from (select count(*)::integer jsonb_object_length from jsonb_object_keys(private.phase8_nutrient_basis_contract()))x;
select ok(not has_function_privilege('authenticated','private.phase8_validate_nutrient_metadata(jsonb)','execute'),'private evidence validator is not exposed');
select ok(private.phase8_evidence_uri_safe('https://example.invalid/food?id=12'),'ordinary source link allowed');
select ok(not private.phase8_evidence_uri_safe('https://user:secret@example.invalid'),'userinfo credentials rejected');
select ok(not private.phase8_evidence_uri_safe('https://example.invalid?%2574oken=secret'),'encoded credential parameter rejected');
select ok(not private.phase8_evidence_uri_safe('https://example.invalid#access_token=secret'),'fragment credential rejected');
select throws_ok($$select private.phase8_validate_nutrient_metadata('{"code":"folate","amount":400,"unit":"ug","definition_basis":"dfe"}')$$,'PT422','incompatible_nutrient_definition','DFE is not silently food folate mass');
select throws_ok($$select private.phase8_validate_nutrient_metadata('{"code":"sodium","amount":1,"unit":"mg","definition_basis":"total_fat"}')$$,'PT422','invalid_nutrient_definition','cross-code basis rejected');
select throws_ok($$select private.phase8_validate_nutrient_metadata('{"code":"protein","amount":1,"unit":"g","value_origin":"official"}')$$,'PT422','invalid_nutrient_source','official requires a source');
select throws_ok($$select private.phase8_validate_nutrient_metadata('{"code":"protein","amount":1,"unit":"g","derivation":{"method":"external_calculation","version":1,"secret":"forbidden"}}')$$,'PT422','invalid_nutrient_derivation','unrestricted derivation keys rejected');
create temp table salt_value as select jsonb_build_object('code','salt_equivalent','amount',2.54,'unit','g','provenance','user_entered','quality','unverified','value_origin','calculated','definition_basis','salt_equivalent_from_sodium','contains_estimates',true,'derivation',jsonb_build_object('method','sodium_to_salt','version',1,'factor_numerator','2.54','factor_denominator','1000','inputs',jsonb_build_array(jsonb_build_object('code','sodium','amount','1000','unit','mg','quality','unverified','value_origin','estimated','definition_basis','elemental_sodium','contains_estimates',true,'source_uri',null,'source_observed_at',null)))) n;
select lives_ok($$select private.phase8_validate_nutrient_metadata(n) from salt_value$$,'exact sodium conversion accepted');
select throws_ok($$select private.phase8_validate_nutrient_metadata(n||'{"amount":2.5}'::jsonb) from salt_value$$,'PT422','invalid_nutrient_derivation','incorrect conversion rejected');
select throws_ok($$select private.phase8_validate_nutrient_metadata(n||'{"value_origin":"official","source_uri":"https://a.invalid"}'::jsonb) from salt_value$$,'PT422','invalid_nutrient_derivation','calculation cannot claim official origin');
create temp table fixtures(kind text primary key,payload jsonb);
insert into fixtures select 'salt',public.create_catalog_item_v3(gen_random_uuid(),2,now(),'ingredient','計算塩',null,100,'g',(select jsonb_build_array(n||'{"quality":"user_verified","contains_estimates":false}'::jsonb) from salt_value));
select ok((select contains_estimates and quality='unverified' and value_origin='calculated' from public.item_nutrients where catalog_item_id=(select (payload->>'item_id')::uuid from fixtures where kind='salt')),'DB cannot drop input estimates or upgrade input quality');
insert into fixtures select 'tiny',public.create_catalog_item_v3(gen_random_uuid(),2,now(),'ingredient','微量',null,100,'g','[{"code":"selenium","amount":0.00000001,"unit":"ug","provenance":"user_entered","quality":"unverified","value_origin":"measured"}]');
select ok((select amount is null and derivation->>'reason'='below_storage_precision' and derivation->>'source_amount'='0.00000001' from public.item_nutrients where catalog_item_id=(select (payload->>'item_id')::uuid from fixtures where kind='tiny')),'raw positive below storage precision is NULL with original evidence');
insert into fixtures select 'source',public.create_catalog_item_v3(gen_random_uuid(),2,now(),'ingredient','少量換算',null,100,'g','[{"code":"selenium","amount":0.000001,"unit":"ug","provenance":"user_entered","quality":"unverified","value_origin":"measured"},{"code":"copper","amount":0,"unit":"mg","provenance":"user_entered","quality":"unverified"}]');
insert into fixtures select 'meal',public.create_meal_entry_v3(gen_random_uuid(),2,now(),current_date,'breakfast',now(),(select (payload->>'item_id')::uuid from fixtures where kind='source'),1,'g',public.get_catalog_reference_fingerprint_v3((select (payload->>'item_id')::uuid from fixtures where kind='source'))->>'reference_fingerprint');
select ok((select amount is null and derivation->>'reason'='below_storage_precision' from public.meal_entry_nutrient_snapshots where meal_entry_id=(select (payload->>'entry_id')::uuid from fixtures where kind='meal') and nutrient_code='selenium'),'new meal tiny positive does not become 0');
select is((select amount from public.meal_entry_nutrient_snapshots where meal_entry_id=(select (payload->>'entry_id')::uuid from fixtures where kind='meal') and nutrient_code='copper'),0::numeric,'actual zero stays zero');
create temp table history_before as select jsonb_agg(to_jsonb(s) order by nutrient_code) payload from public.meal_entry_nutrient_snapshots s where meal_entry_id=(select (payload->>'entry_id')::uuid from fixtures where kind='meal');
insert into fixtures select 'batch',to_jsonb(public.create_batch('微量レシピ',null,100,'食',jsonb_build_array(jsonb_build_object('catalog_item_id',(select payload->>'item_id' from fixtures where kind='source'),'quantity',1,'quantity_unit','g')),'evidence-tiny-batch'));
select ok((select amount is null and derivation->>'reason'='below_storage_precision' from public.item_nutrients where catalog_item_id=(select (payload->>'id')::uuid from fixtures where kind='batch') and nutrient_code='selenium'),'batch tiny positive stays indeterminate');
select ok(not private.phase8_nutrient_output_compatible('vitamin_a','ug_rae','ug_rae',500,null,'https://world.openfoodfacts.org/product/1'),'ambiguous legacy OFF vitamin A excluded');
select ok(not private.phase8_nutrient_output_compatible('vitamin_e','mg','mg',1,'total_tocopherol',null),'total tocopherol not alpha tocopherol');
select ok(not private.phase8_nutrient_output_compatible('n3_fatty_acids','g','g',1,'ala_only',null),'ALA alone not total n3');
select ok(private.phase8_nutrient_output_compatible('vitamin_a','ug_rae','ug_rae',500,'rae',null),'matching RAE accepted');
insert into private.chat_registration_targets(target_alias,user_id) values ('evidence-v2','11111111-1111-4111-8111-111111111711');
create temp table chat_payload as select jsonb_build_object('schema_version',2,'registration_mode','direct','request_id',gen_random_uuid(),'meal',jsonb_build_object('meal_date',current_date,'meal_type','lunch','eaten_at',now()),'items',jsonb_build_array(jsonb_build_object('name','Chat計算','serving_size',100,'serving_unit','g','quantity',1,'nutrients',(select jsonb_build_array(n||'{"provenance":"calculated"}'::jsonb) from salt_value)))) p;
insert into fixtures select 'chat',private.register_meal_from_chat_v2('evidence-v2',(p->>'request_id')::uuid,p) from chat_payload;
select ok((select contains_estimates and derivation->>'method'='sodium_to_salt' and value_origin='calculated' from public.meal_entry_nutrient_snapshots where meal_entry_id=(select (payload->'entries'->0->>'entry_id')::uuid from fixtures where kind='chat') and nutrient_code='salt_equivalent'),'Chat direct v2 keeps calculated source and estimates');
select is((select jsonb_agg(to_jsonb(s) order by nutrient_code) from public.meal_entry_nutrient_snapshots s where meal_entry_id=(select (payload->>'entry_id')::uuid from fixtures where kind='meal')),(select payload from history_before),'historical snapshots remain byte-for-byte unchanged');
select * from finish();
rollback;
